"use client";
/**
 * One size variant inside the model editor (BRD-02/05/06/13, F10): sizes as the shaper writes them (5'10",
 * 20 1/2, 52 см), volume, material, fins, construction, price, made-to-order days and «в наличии, шт.» (the
 * server turns them into «В наличии / Под заказ / Нет в наличии»). The SKU is generated by the server and only
 * shown. A variant that already has orders gets the versioning notice: changing its specification creates a new
 * version with a new SKU while past orders keep their snapshot.
 */
import { FIN_SYSTEM_LABELS, type Material } from "@/lib/api/shaper";
import { cx } from "@/lib/cx";
import { StatusBadge } from "@/components/ui/Badge";
import { Select, TextInput } from "@/components/ui/Field";
import { Icon } from "@/components/ui/Icon";
import { willVersion, type VariantDraft, type VariantField } from "./draft";

const finOptions = Object.entries(FIN_SYSTEM_LABELS).map(([value, label]) => ({ value, label }));

export function VariantEditor({
  index,
  draft,
  original,
  materials,
  errors = {},
  onChange,
  onRemove,
  canRemove,
  disabled,
}: {
  index: number;
  draft: VariantDraft;
  original?: VariantDraft;
  materials: Material[];
  errors?: Partial<Record<VariantField | "_form", string>>;
  onChange: (field: VariantField, value: string) => void;
  onRemove: () => void;
  canRemove: boolean;
  disabled?: boolean;
}) {
  const id = (f: string) => `v-${draft.key}-${f}`;
  const versioning = willVersion(draft, original);
  const materialOptions = materials.map((m) => ({ value: String(m.id), label: m.is_custom ? `${m.name} (свой)` : m.name }));
  if (draft.material_id && !materialOptions.some((o) => o.value === draft.material_id)) {
    materialOptions.push({ value: draft.material_id, label: "Материал недоступен" });
  }
  const label = `Вариант ${index + 1}`;
  return (
    <fieldset className={cx("gv-sc-variant", Object.keys(errors).length > 0 && "has-error")} aria-describedby={errors._form ? id("error") : undefined}>
      <legend className="gv-sc-variant-head">
        <span className="gv-sc-variant-title">{label}</span>
        <span className="gv-article" title="Артикул присваивает сервер: код шейпера · тип · длина · ширина · номер модели">
          {draft.sku ? `Арт. ${draft.sku}` : "Артикул присвоится после сохранения"}
        </span>
        {draft.version && draft.version > 1 ? <span className="gv-sc-version">версия {draft.version}</span> : null}
        {draft.availability ? <StatusBadge domain="availability" status={draft.availability} /> : null}
      </legend>
      {canRemove && (
        <button type="button" className="gv-sc-variant-remove" onClick={onRemove} disabled={disabled} aria-label={`Удалить ${label.toLowerCase()}${draft.sku ? ` (${draft.sku})` : ""}`}>
          <Icon name="close" size={15} />
        </button>
      )}
      {original?.has_orders && (
        <p className={cx("gv-sc-version-note", versioning && "is-active")} role={versioning ? "status" : undefined}>
          <Icon name="info" size={14} />
          {versioning
            ? "Вы меняете параметры размера, по которому уже есть заказы: при сохранении появится новая версия с новым артикулом, а прошлые заказы сохранят прежние параметры."
            : "По этому размеру уже есть заказы: изменение размеров, материала, конструкции или закладных создаст новую версию с новым артикулом. Цена, срок и наличие меняются без новой версии."}
        </p>
      )}
      <div className="gv-sc-variant-grid">
        <TextInput id={id("length")} label="Длина" required placeholder={`5'10"`} value={draft.length} onChange={(e) => onChange("length", e.target.value)} error={errors.length} hint={`5'10", 70 или 178 см`} disabled={disabled} />
        <TextInput id={id("width")} label="Ширина, дюймы" required placeholder="20 1/2" value={draft.width} onChange={(e) => onChange("width", e.target.value)} error={errors.width} disabled={disabled} />
        <TextInput id={id("thickness")} label="Толщина, дюймы" placeholder="2 5/8" value={draft.thickness} onChange={(e) => onChange("thickness", e.target.value)} error={errors.thickness} disabled={disabled} />
        <TextInput id={id("volume")} label="Объём, л" inputMode="decimal" placeholder="35,2" value={draft.volume} onChange={(e) => onChange("volume", e.target.value)} error={errors.volume} disabled={disabled} />
        <Select id={id("material_id")} label="Материал" placeholder="Не указан" options={materialOptions} value={draft.material_id} onChange={(e) => onChange("material_id", e.target.value)} error={errors.material_id} disabled={disabled} />
        <Select id={id("fin_system")} label="Вид закладных" options={finOptions} value={draft.fin_system} onChange={(e) => onChange("fin_system", e.target.value)} error={errors.fin_system} disabled={disabled} />
        <TextInput id={id("fin_setup")} label="Плавники" placeholder="Thruster, 2+1, Quad" maxLength={40} value={draft.fin_setup} onChange={(e) => onChange("fin_setup", e.target.value)} error={errors.fin_setup} disabled={disabled} />
        <TextInput id={id("construction")} label="Конструкция" placeholder="PU / полиэстер, EPS / эпоксид" maxLength={80} value={draft.construction} onChange={(e) => onChange("construction", e.target.value)} error={errors.construction} disabled={disabled} />
        <TextInput id={id("price")} label="Цена, ₽" inputMode="decimal" placeholder="65000" value={draft.price} onChange={(e) => onChange("price", e.target.value)} error={errors.price} hint="Пусто — «по договорённости»" disabled={disabled} />
        <TextInput
          id={id("made_to_order_days")}
          label="Изготовление под заказ, дней"
          inputMode="numeric"
          placeholder="21"
          value={draft.made_to_order_days}
          onChange={(e) => onChange("made_to_order_days", e.target.value.replace(/\D/g, ""))}
          error={errors.made_to_order_days}
          hint="0 — срок по договорённости; пусто — не делаю под заказ"
          disabled={disabled}
        />
        <TextInput
          id={id("in_stock_quantity")}
          label="В наличии, шт."
          inputMode="numeric"
          value={draft.in_stock_quantity}
          onChange={(e) => onChange("in_stock_quantity", e.target.value.replace(/\D/g, ""))}
          error={errors.in_stock_quantity}
          hint="Готовые доски на продажу — статус «В наличии» считается по ним"
          disabled={disabled}
        />
        <TextInput
          id={id("sku_suffix")}
          label="Суффикс артикула"
          placeholder="EPS"
          maxLength={8}
          value={draft.sku_suffix}
          onChange={(e) => onChange("sku_suffix", e.target.value.toUpperCase())}
          error={errors.sku_suffix}
          hint="Только если у модели два варианта одного размера"
          disabled={disabled}
        />
      </div>
      {errors._form && (
        <p id={id("error")} className="gv-sc-form-error" role="alert">
          <Icon name="alert" size={14} /> {errors._form}
        </p>
      )}
    </fieldset>
  );
}
